// ai-agents/shared/src/jira.ts (sketch): every Jira call goes through one small function
const BASE = process.env.JIRA_BASE_URL!; // https://rhino-fcp.atlassian.net, or the api.atlassian.com form for scoped tokens
const AUTH = "Basic " + Buffer.from(`${process.env.JIRA_EMAIL}:${process.env.JIRA_API_TOKEN}`).toString("base64");

export const jiraFetch = async <T>(path: string, init: RequestInit = {}): Promise<T | undefined> => {
  for (let attempt = 1; ; attempt++) {
    const res = await fetch(`${BASE}${path}`, { ...init, headers: { Authorization: AUTH, Accept: "application/json",
      "Content-Type": "application/json", ...init.headers } });
    if (res.status === 429 && attempt < 5) { // rate limited: wait as long as Jira asks
      const wait = Number(res.headers.get("Retry-After") ?? 5) * 1000;
      await new Promise((r) => setTimeout(r, wait));
      continue;
    }
    if (res.status === 404) return undefined; // for example an issue property that was never set
    if (!res.ok) throw new Error(`Jira ${init.method ?? "GET"} ${path}: ${res.status} ${await res.text()}`);
    return res.status === 204 ? undefined : ((await res.json()) as T);
  }
};

// ai-agents/shared/src/jira.ts (search): POST /rest/api/3/search/jql, paged with nextPageToken
interface SearchPage { issues: JiraIssue[]; nextPageToken?: string }

export const searchAll = async (jql: string, fields = ["summary", "status", "assignee", "updated"]) => {
  const all: JiraIssue[] = [];
  let nextPageToken: string | undefined;
  do {
    const page = await jiraFetch<SearchPage>("/rest/api/3/search/jql", {
      method: "POST", body: JSON.stringify({ jql, fields, maxResults: 100, nextPageToken }),
    });
    all.push(...(page?.issues ?? []));
    nextPageToken = page?.nextPageToken;
  } while (nextPageToken);
  return all;
};

// ai-agents/shared/src/jira.ts (issue properties): small JSON values an app stores on an issue
const propPath = (key: string, name: string) => `/rest/api/3/issue/${key}/properties/${encodeURIComponent(name)}`;

export const issueProperty = async <T>(key: string, name: string): Promise<T | undefined> =>
  (await jiraFetch<{ key: string; value: T }>(propPath(key, name)))?.value; // 404: undefined

export const setIssueProperty = (key: string, name: string, value: unknown) =>
  jiraFetch(propPath(key, name), { method: "PUT", body: JSON.stringify(value) });

