// ai-agents/shared/src/jira.ts (changelog): every field change, oldest first, 100 per page
interface ChangeItem { field: string; from: string | null; to: string | null }
interface Change { author: { accountId: string }; created: string; items: ChangeItem[] }

export const changelog = async (key: string): Promise<Change[]> => {
  const all: Change[] = [];
  for (let startAt = 0; ; startAt += 100) {
    const page = await jiraFetch<{ values: Change[]; isLast: boolean }>(`/rest/api/3/issue/${key}/changelog?startAt=${startAt}&maxResults=100`);
    all.push(...(page?.values ?? []));
    if (!page || page.isLast) return all;
  }
};

// ai-agents/orchestrator/src/triggers/nova.ts (G4-04): who handed the ticket to Nova
export async function requesterOf(key: string): Promise<string | undefined> {
  const fromSlack = await jira.issueProperty<string>(key, "nova.requester"); // set by /nova in Slack
  if (fromSlack) return fromSlack;
  const history = await jira.changelog(key); // oldest first
  const toNova = history.filter((h) => h.items.some((i) => i.field === "assignee" && i.to === jira.me));
  return toNova.at(-1)?.author.accountId;
}
